// Built-in AZ-400 practice questions (original content, not taken from any exam or dump site).
// Same shape as an importable question file; see sample-questions.json and README.md.
window.BUILTIN_QUESTIONS = [
  // Foundations: beginner questions on the core ideas the exam-level questions build on.
  { id: 'f01', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/devops/what-is-devops', question: 'Which statement best describes DevOps?', options: ['A job title for people who run servers', 'A single tool that builds and deploys code', 'The union of people, process and technology to continually deliver value to customers', 'A rule that developers must also be system administrators'], answer: 2, explanation: 'DevOps is a way of working, not one tool or role. Development and operations share goals, practices and automation so changes reach users quickly and safely.' },
  { id: 'f02', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/devops/develop/what-is-continuous-integration', question: 'What does continuous integration (CI) mean?', options: ['Every change is merged often and automatically built and tested', 'Code is merged once at the end of the project', 'Servers are patched automatically every night', 'Production is deployed every time someone opens a pull request'], answer: 0, explanation: 'In CI, developers merge small changes frequently, and each merge triggers an automatic build and test run, so problems show up within minutes instead of weeks.' },
  { id: 'f03', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/devops/deliver/what-is-continuous-delivery', question: 'What is the difference between continuous delivery and continuous deployment?', options: ['There is no difference', 'Continuous delivery keeps every change ready to release but a person approves production; continuous deployment releases to production automatically', 'Continuous delivery skips testing; continuous deployment does not', 'Continuous deployment only applies to mobile apps'], answer: 1, explanation: 'Both automate the path to production. With continuous delivery, the last step into production waits for a decision, often an approval. With continuous deployment, every change that passes the pipeline goes live automatically.' },
  { id: 'f04', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/get-started/key-pipelines-concepts', question: 'In an Azure Pipelines YAML file, how are the building blocks nested, from largest to smallest?', options: ['Steps contain jobs, and jobs contain stages', 'Stages contain jobs, and jobs contain steps', 'Jobs contain stages, and stages contain steps', 'Tasks contain pipelines'], answer: 1, explanation: 'A pipeline has one or more stages, such as Build and Deploy. Each stage has jobs, each job runs on one agent, and each job is a list of steps: scripts or tasks.' },
  { id: 'f05', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/get-started/pipelines-get-started', question: 'Where is a YAML pipeline definition stored?', options: ['Only in the Azure DevOps web portal database', 'In a file in the repository, versioned alongside the code', 'On the build agent\'s hard disk', 'In an Azure Storage account'], answer: 1, explanation: 'YAML pipelines are "pipeline as code": the file (often azure-pipelines.yml) lives in the repository, so pipeline changes go through the same history and pull requests as code changes.' },
  { id: 'f06', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/agents/hosted', question: 'What is a Microsoft-hosted agent?', options: ['A support engineer who watches your pipeline', 'A fresh virtual machine, maintained by Microsoft, that runs a job and is then discarded', 'A server in your own data centre', 'A browser plug-in for Azure DevOps'], answer: 1, explanation: 'Microsoft-hosted agents are VMs with common tools already installed. Each job gets a clean one, which is simple and secure, but nothing is kept between runs and they cannot reach private networks.' },
  { id: 'f07', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/build/triggers', question: 'In YAML, which keyword makes a pipeline run automatically when code is pushed to a branch?', options: ['trigger', 'schedule', 'stage', 'pool'], answer: 0, explanation: 'trigger defines the CI trigger: which branches (and optionally paths) start a run on push. pool chooses the agents, and stage defines a phase of the pipeline.' },
  { id: 'f08', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/variables', question: 'Why use pipeline variables instead of writing values directly into every step?', options: ['Variables make pipelines run faster', 'A value is defined once and reused, and can differ per run, stage or environment', 'Variables are required for every task', 'Variables encrypt the whole pipeline'], answer: 1, explanation: 'Variables keep a value in one place, such as a resource group name or build configuration, and let you change it per run or per stage without editing every step.' },
  { id: 'f09', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/set-secret-variables', question: 'What happens when a pipeline variable is marked as secret?', options: ['It is printed in bold in the logs', 'Its value is encrypted and masked as *** in logs', 'It can only be used on weekends', 'It is copied to every repository'], answer: 1, explanation: 'Secret variables are stored encrypted, are not shown after saving, and are masked if they appear in log output. They also are not passed to scripts as environment variables unless you map them explicitly.' },
  { id: 'f10', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/artifacts/pipeline-artifacts', question: 'In a pipeline, what is a build artifact?', options: ['A bug found during the build', 'The files produced by a build, such as a package, published so later stages can use them', 'The YAML file itself', 'A comment left on a pull request'], answer: 1, explanation: 'The build stage publishes its output, for example a zip or container image, as an artifact. Deploy stages download that exact artifact, so what you tested is what you release.' },
  { id: 'f11', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/library/service-endpoints', question: 'What is a service connection in Azure DevOps?', options: ['A chat channel for the team', 'A saved, secured way for pipelines to authenticate to an external service such as Azure', 'A network cable between agents', 'A link between two work items'], answer: 1, explanation: 'Service connections hold the identity details pipelines use to reach Azure, container registries, GitHub and other services, so credentials are not written into the pipeline.' },
  { id: 'f12', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/environments', question: 'What is an environment in Azure Pipelines?', options: ['The operating system of the agent', 'A named deployment target, such as Production, that records deployment history and can have approvals and checks', 'A variable group', 'A branch in the repository'], answer: 1, explanation: 'Environments represent where you deploy. They show which runs deployed there, and you can protect them with approvals and checks.' },
  { id: 'f13', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/user-guide/what-is-azure-devops', question: 'Which Azure DevOps service hosts private NuGet, npm, Maven and Python packages?', options: ['Azure Boards', 'Azure Repos', 'Azure Artifacts', 'Azure Test Plans'], answer: 2, explanation: 'Azure Boards tracks work, Azure Repos hosts Git repositories, Azure Pipelines builds and deploys, Azure Test Plans manages manual and exploratory testing, and Azure Artifacts hosts package feeds.' },
  { id: 'f14', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/boards/work-items/about-work-items', question: 'What is a work item in Azure Boards?', options: ['A pipeline run', 'A record that tracks a piece of work, such as a user story, bug or task', 'A file in the repository', 'A virtual machine'], answer: 1, explanation: 'Work items track what the team plans and does. They can be linked to commits, pull requests and builds for traceability.' },
  { id: 'f15', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/devops/plan/what-is-scrum', question: 'In Scrum, what is a sprint?', options: ['A fixed timebox, often two weeks, in which the team delivers a usable increment', 'The fastest way to deploy', 'A meeting held once a year', 'A type of branch'], answer: 0, explanation: 'A sprint is a short, fixed period with a goal. It starts with planning and ends with a review and a retrospective, then the next sprint begins.' },
  { id: 'f16', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/devops/develop/git/what-is-git', question: 'What is a Git branch?', options: ['A backup copy of the whole server', 'A movable pointer to a line of commits, letting work happen separately from main', 'A folder that cannot be deleted', 'A pipeline stage'], answer: 1, explanation: 'Branches let you work on a change without affecting main. When the work is ready, it is merged back, usually through a pull request.' },
  { id: 'f17', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/repos/git/clone', question: 'Which Git command copies a remote repository to your computer for the first time?', options: ['git push', 'git clone', 'git commit', 'git merge'], answer: 1, explanation: 'git clone downloads the repository with its history and sets up the remote named origin. After that you use pull to get updates and push to send your commits.' },
  { id: 'f18', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/repos/git/pushing', question: 'You have made commits on your computer. Which command sends them to the shared repository?', options: ['git push', 'git fetch', 'git status', 'git init'], answer: 0, explanation: 'Commits are local until you push them. git fetch and git pull bring changes the other way, from the remote to you.' },
  { id: 'f19', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/repos/git/about-pull-requests', question: 'What is the main purpose of a pull request?', options: ['To download the latest code', 'To propose changes so they can be reviewed, discussed and checked before merging', 'To delete a branch', 'To restart a pipeline'], answer: 1, explanation: 'A pull request shows the changes, gathers reviewer comments and approvals, runs policy checks such as builds, and then merges when everything passes.' },
  { id: 'f20', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/devops/repos/git/merging', question: 'When does a merge conflict happen?', options: ['When two branches change the same lines of the same file in different ways', 'Every time you merge', 'When a pipeline fails', 'When a branch name has a space'], answer: 0, explanation: 'Git merges most changes automatically. It stops and asks you to choose only when both sides edited the same part of a file differently.' },
  { id: 'f21', domain: 'Foundations', learn: 'https://docs.github.com/en/actions/get-started/understand-github-actions', question: 'Where do GitHub Actions workflow files live in a repository?', options: ['/pipelines', '.github/workflows', '/actions', 'The repository settings page only'], answer: 1, explanation: 'Workflows are YAML files in .github/workflows. In GitHub Actions, the machine that runs a job is called a runner, the equivalent of an Azure Pipelines agent.' },
  { id: 'f22', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/devops/deliver/what-is-infrastructure-as-code', question: 'What is infrastructure as code (IaC)?', options: ['Writing application code on a server', 'Defining servers, networks and other resources in files that are versioned and deployed like code', 'Drawing architecture diagrams', 'Buying hardware online'], answer: 1, explanation: 'With IaC, such as Bicep or Terraform, environments are created from files in source control, so they are repeatable, reviewable and easy to recreate.' },
  { id: 'f23', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/devops/develop/shift-left-make-testing-fast-reliable', question: 'What does "shift left" mean in DevOps?', options: ['Move servers to another region', 'Do testing and security checks earlier in the development process', 'Release on Mondays', 'Put the newest code on the left of the screen'], answer: 1, explanation: 'Problems are cheaper to fix the earlier they are found. Shifting left means running tests, code analysis and security scans during development and in pull requests, not just before release.' },
  { id: 'f24', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/dotnet/core/testing/', question: 'Which kind of test checks one small piece of code in isolation and runs in milliseconds?', options: ['Load test', 'Unit test', 'Manual acceptance test', 'Penetration test'], answer: 1, explanation: 'Unit tests are small and fast, so CI runs them on every change. Integration, load and acceptance tests cover more but take longer.' },
  { id: 'f25', domain: 'Foundations', learn: 'https://learn.microsoft.com/en-us/azure/azure-monitor/app/app-insights-overview', question: 'What is Application Insights?', options: ['A code editor', 'A feature of Azure Monitor that collects requests, errors, dependencies and performance data from your app', 'A Git hosting service', 'A test management tool'], answer: 1, explanation: 'Application Insights is application performance monitoring in Azure Monitor. Your app sends telemetry to it, and you explore that telemetry with charts, the application map and KQL queries.' },

  { id: 'q01', learn: 'https://learn.microsoft.com/en-us/azure/devops/repos/git/git-branching-guidance', domain: 'Source control', question: 'Your team wants main to stay releasable at all times. Developers should merge small changes several times a day through pull requests. Which branching strategy fits best?', options: ['GitFlow with long-lived develop and release branches', 'Trunk-based development with short-lived feature branches', 'A fork per developer, merged at the end of each sprint', 'One long-lived branch per environment (dev, test, prod)'], answer: 1, explanation: 'Trunk-based development keeps branches short-lived and merges to main often through pull requests, so main stays deployable. GitFlow and per-environment branches create long-lived divergence and painful merges.' },
  { id: 'q02', learn: 'https://learn.microsoft.com/en-us/azure/devops/repos/git/branch-policies', domain: 'Source control', question: 'In Azure Repos, a pull request into main must not complete unless the CI pipeline succeeds on the merged code. Which branch policy do you configure?', options: ['Require a minimum number of reviewers', 'Check for linked work items', 'Build validation', 'Check for comment resolution'], answer: 2, explanation: 'A build validation policy queues the pipeline against the pull request merge result and blocks completion until it passes. The other policies govern reviews, traceability and discussion, not build results.' },
  { id: 'q03', learn: 'https://learn.microsoft.com/en-us/azure/devops/repos/git/manage-large-files', domain: 'Source control', question: 'A repository holds large design and video files, and clones have become slow. The files must stay versioned but out of the normal Git object history. What should you use?', options: ['Git submodules', 'Git Large File Storage (LFS)', 'A .gitignore rule', 'Squash merges on every pull request'], answer: 1, explanation: 'Git LFS stores small pointers in the repository and keeps the file content on the LFS server, so the files stay versioned without bloating history. A .gitignore rule stops versioning them at all; submodules and squash merges do not address large binaries.' },
  { id: 'q04', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/repos/azure-repos-git', domain: 'Pipelines', question: 'Complete the YAML so the pipeline runs only for commits to main that change files under src.', code: 'trigger:\n  branches:\n    include:\n    - main\n  ______:\n    include:\n    - src', options: ['pr', 'paths', 'filters', 'directories'], answer: 1, explanation: 'Path filters sit under trigger as paths with include and exclude lists, next to the branches filter. pr defines pull request triggers; filters and directories are not valid keywords.' },
  { id: 'q05', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/release/caching', domain: 'Pipelines', question: 'A .NET pipeline spends most of its time restoring NuGet packages. Which two actions reduce the duration of each run?', options: ['Add a Cache@2 task keyed on packages.lock.json', 'Set batch: true on the CI trigger', 'Run on a self-hosted agent that keeps dependencies between runs', 'Increase the pipeline retention period'], answer: [0, 2], explanation: 'Cache@2 restores the package folder when the lock file has not changed, and a self-hosted agent keeps warm caches on disk. batch: true reduces how many runs start, not how long each one takes; retention only controls how long runs are kept.' },
  { id: 'q06', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/deployment-jobs', domain: 'Pipelines', question: 'You want to release a new API version to about 5% of users, watch error rates, and then widen the rollout or roll back. Which deployment pattern is this?', options: ['Blue-green', 'Canary', 'Recreate', 'Rolling update across all instances at once'], answer: 1, explanation: 'A canary release sends a small slice of traffic to the new version first and widens only while metrics stay healthy. Blue-green moves all traffic between two full environments in one step.' },
  { id: 'q07', learn: 'https://learn.microsoft.com/en-us/azure/azure-app-configuration/concept-feature-management', domain: 'Pipelines', question: 'Developers want to ship unfinished features to production switched off, then turn them on for a pilot group at runtime without redeploying. What should you implement?', options: ['Deployment slot swaps in App Service', 'Feature flags with Azure App Configuration feature management', 'A separate release branch per feature', 'A pipeline variable that selects the feature at build time'], answer: 1, explanation: 'Feature flags separate deployment from release: the code ships dark, and the flag with a targeting filter turns it on for chosen users at runtime. Slots, branches and build-time variables all need a new deployment to change who sees the feature.' },
  { id: 'q08', learn: 'https://learn.microsoft.com/en-us/azure/devops/artifacts/concepts/upstream-sources', domain: 'Pipelines', question: 'Teams need a private NuGet feed that can also serve public packages from nuget.org, keeping a saved copy of each public package they use. What should you set up?', options: ['An Azure Artifacts feed with nuget.org as an upstream source', 'A file share that every build agent maps as a local feed', 'GitHub Releases with the .nupkg files attached', 'Private packages published to nuget.org'], answer: 0, explanation: 'Azure Artifacts feeds support upstream sources: a package pulled from nuget.org through the feed is saved in the feed, so builds keep working even if the public package changes or is removed.' },
  { id: 'q09', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/approvals', domain: 'Pipelines', question: 'In a multi-stage YAML pipeline, a release manager must approve before anything deploys to production. What should you configure?', options: ['A required reviewers branch policy on main', 'An approval check on the Production environment, targeted by a deployment job', 'A condition of succeeded() on the production stage', 'Open access on the production service connection'], answer: 1, explanation: 'YAML pipelines use approvals and checks on protected resources. Add an approval to the Production environment and deploy with a deployment job that targets it; the run waits there until someone approves.' },
  { id: 'q10', learn: 'https://learn.microsoft.com/en-us/azure/azure-resource-manager/bicep/overview', domain: 'Pipelines', question: 'You need Azure-native, declarative infrastructure as code with concise modular syntax, a what-if preview, and no separate state file to manage. What should you use?', options: ['Bicep', 'Terraform', 'Azure CLI scripts', 'Azure Resource Graph queries'], answer: 0, explanation: 'Bicep compiles to ARM templates, supports modules and what-if, and relies on Azure itself for state. Terraform keeps a state file; CLI scripts are imperative; Resource Graph only queries existing resources.' },
  { id: 'q11', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/agents/agents', domain: 'Pipelines', question: 'A pipeline must deploy to a virtual machine that is reachable only inside a private virtual network with no public endpoint. What should run the deployment job?', options: ['A Microsoft-hosted agent with more parallel jobs', 'A Microsoft-hosted agent whose IP range is allowed on the VM', 'A self-hosted agent or Managed DevOps Pool connected to that virtual network', 'The same agent with a longer job timeout'], answer: 2, explanation: 'Microsoft-hosted agents run outside your network and cannot reach an endpoint that is private only. An agent that runs inside, or is injected into, the virtual network can.' },
  { id: 'q12', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/library/link-variable-groups-to-key-vaults', domain: 'Security', question: 'Pipelines in several projects use the same database password. Security wants to rotate it in one place without editing any pipeline. What should you do?', options: ['Add a secret variable to each pipeline', 'Link a variable group to Azure Key Vault and reference the group in each pipeline', 'Commit the password encrypted in appsettings.json', 'Upload the password as a secure file'], answer: 1, explanation: 'A variable group linked to Key Vault reads the secret at run time, so rotating it in Key Vault updates every pipeline that uses the group. Per-pipeline secrets each need editing, and secrets in the repository are a leak risk.' },
  { id: 'q13', learn: 'https://docs.github.com/en/code-security/concepts/supply-chain-security/dependabot-alerts', domain: 'Security', question: 'In GitHub, you want alerts when a repository depends on open-source packages with known vulnerabilities, plus automatic pull requests that upgrade them. What should you enable?', options: ['CodeQL code scanning', 'Secret scanning push protection', 'Dependabot alerts and security updates', 'A CODEOWNERS file'], answer: 2, explanation: 'Dependabot checks your dependency graph against the GitHub Advisory Database, raises alerts and can open upgrade pull requests. CodeQL analyses your own code, secret scanning finds leaked credentials, and CODEOWNERS routes reviews.' },
  { id: 'q14', learn: 'https://learn.microsoft.com/en-us/kusto/query/', domain: 'Instrumentation', question: 'A web app sends telemetry to Application Insights. You need to find slow outbound dependency calls. Which language do you use to query the data in Log Analytics?', options: ['Kusto Query Language (KQL)', 'Transact-SQL', 'PromQL', 'Gremlin'], answer: 0, explanation: 'Application Insights and Log Analytics data is queried with KQL, for example the dependencies table filtered and summarized by duration.' },
  { id: 'q15', learn: 'https://learn.microsoft.com/en-us/azure/azure-monitor/app/availability', domain: 'Instrumentation', question: 'You must be alerted when a public website stops responding from several geographic regions, even when no users are visiting it. What should you configure?', options: ['An Application Insights availability test', 'A Log Analytics workspace retention policy', 'Azure Advisor recommendations', 'A diagnostic setting on the App Service plan'], answer: 0, explanation: 'Availability tests call the endpoint on a schedule from multiple Azure regions and can fire an alert when checks fail, independent of real user traffic.' },
  { id: 'q16', learn: 'https://learn.microsoft.com/en-us/azure/devops/boards/github/link-to-from-github', domain: 'Process', question: 'Code is in GitHub and work is tracked in Azure Boards. After connecting the repository to Azure Boards, what should developers put in commit messages to link commits to work items?', options: ['#1234', 'AB#1234', 'WI-1234', 'Fixes: 1234'], answer: 1, explanation: 'With the Azure Boards app connected, the AB#<ID> syntax links commits and pull requests to the work item. #1234 refers to a GitHub issue or pull request.' },
  { id: 'q17', learn: 'https://dora.dev/guides/dora-metrics/', domain: 'Process', question: 'Which DORA metric measures the time from a commit to that code running successfully in production?', options: ['Deployment frequency', 'Lead time for changes', 'Change failure rate', 'Failed deployment recovery time'], answer: 1, explanation: 'Lead time for changes tracks commit-to-production time. Deployment frequency counts releases, change failure rate is the share of deployments that cause failures, and recovery time is how fast service is restored.' },

  { id: 'q18', learn: 'https://learn.microsoft.com/en-us/azure/devops/boards/work-items/guidance/choose-process', domain: 'Process', question: 'A new Azure DevOps project must track Epics, Features, User Stories, Tasks and Bugs. Which inherited process should you choose?', options: ['Basic', 'Agile', 'Scrum', 'CMMI'], answer: 1, explanation: 'The Agile process uses User Story as its backlog item. Scrum uses Product Backlog Item, CMMI uses Requirement, and Basic uses Issue.' },
  { id: 'q19', learn: 'https://learn.microsoft.com/en-us/azure/devops/report/dashboards/cycle-time-and-lead-time', domain: 'Process', question: 'In Azure Boards analytics, which measure is the time from when work on an item starts until it is completed?', options: ['Lead time', 'Cycle time', 'Velocity', 'Burndown'], answer: 1, explanation: 'Cycle time starts when an item first enters an In Progress state. Lead time starts earlier, when the item is created. Velocity and burndown measure amounts of work, not time per item.' },
  { id: 'q20', learn: 'https://learn.microsoft.com/en-us/azure/devops/project/wiki/publish-repo-to-wiki', domain: 'Process', question: 'Developers want to write documentation as Markdown in a repository folder, review it through pull requests, and have it appear in Azure DevOps as a wiki. What should you use?', options: ['The project wiki', 'Publish code as wiki', 'A README.md in each folder', 'A dashboard Markdown widget'], answer: 1, explanation: 'Publish code as wiki turns a folder in a Git repository into a wiki, so pages are versioned and changed through pull requests like code. The project wiki lives in its own separate repository.' },
  { id: 'q21', learn: 'https://learn.microsoft.com/en-us/azure/devops/repos/git/branch-policies', domain: 'Process', question: 'Every pull request into main must reference the work item it delivers. Which Azure Repos branch policy enforces this?', options: ['Build validation', 'Check for linked work items, set to Required', 'Limit merge types', 'Automatically included reviewers'], answer: 1, explanation: 'The linked work items policy blocks completion until at least one work item is linked, when set to Required. Optional only shows a warning.' },

  { id: 'q22', learn: 'https://learn.microsoft.com/en-us/azure/devops/repos/git/merging-with-squash', domain: 'Source control', question: 'You want main to have a linear history where each completed pull request appears as a single commit. Which merge type should you allow?', options: ['Merge (no fast-forward)', 'Squash commit', 'Semi-linear merge', 'Rebase with merge commit'], answer: 1, explanation: 'A squash merge combines all of a pull request\'s commits into one new commit on the target branch, giving a linear history. A no-fast-forward merge keeps every commit and adds a merge commit.' },
  { id: 'q23', learn: 'https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/removing-sensitive-data-from-a-repository', domain: 'Source control', question: 'A developer pushed a commit containing a storage account key to a shared repository. What should you do first?', options: ['Rewrite history with git filter-repo and force-push', 'Revert the commit', 'Rotate or revoke the exposed key', 'Make the repository private'], answer: 2, explanation: 'Treat the key as compromised the moment it is pushed: clones and forks may already hold it. Rotate it first; cleaning history comes after and cannot recall copies that already exist.' },
  { id: 'q24', learn: 'https://git-scm.com/docs/git-sparse-checkout', domain: 'Source control', question: 'A monorepo is very large, but each team only works in its own folder. You want faster clones and a smaller working tree. Which Git features help most?', options: ['Partial clone with sparse-checkout', 'git gc --aggressive', 'Git submodules for every folder', 'A shallow clone of every branch'], answer: 0, explanation: 'A partial clone downloads objects only when they are needed, and sparse-checkout limits the working tree to the folders you choose. Together they cut download size and checkout time.' },
  { id: 'q25', learn: 'https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-code-owners', domain: 'Source control', question: 'In GitHub, changes under /infra must be approved by the platform team before merging. Which two settings do you combine?', options: ['A CODEOWNERS file that maps /infra to the platform team', 'A branch rule that requires review from Code Owners', 'A required status check for CodeQL', 'Dependabot version updates'], answer: [0, 1], explanation: 'CODEOWNERS maps paths to owners and requests their review automatically. The branch protection or ruleset setting "Require review from Code Owners" makes that review mandatory before merging.' },
  { id: 'q26', learn: 'https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-protected-branches/about-protected-branches', domain: 'Source control', question: 'Your security team requires proof that every commit on main was made by a verified author. What should you enable on the GitHub branch?', options: ['Require linear history', 'Require signed commits', 'Require conversation resolution', 'Lock branch'], answer: 1, explanation: 'Require signed commits rejects commits that are not signed with a verified GPG, SSH or S/MIME key.' },

  { id: 'q27', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/templates', domain: 'Pipelines', question: 'Twenty YAML pipelines repeat the same build and scan steps. You want to maintain those steps in one place. What should you use?', options: ['Task groups in the classic editor', 'YAML templates in a shared repository referenced through resources.repositories', 'A variable group', 'Copy the steps into a pipeline and clone it'], answer: 1, explanation: 'YAML templates hold reusable stages, jobs or steps. Keep them in a shared repository and reference them with resources.repositories, then use template: or extends:. Task groups are for classic pipelines only.' },
  { id: 'q28', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/security/templates', domain: 'Pipelines', question: 'Security requires that any pipeline deploying to the Production environment extends an approved template. How do you enforce this?', options: ['Add a Required template check to the Production environment', 'Add a branch policy on the template repository', 'Mark the template file read-only', 'Add a manual validation task to each pipeline'], answer: 0, explanation: 'The Required template check on a protected resource (an environment, service connection or agent pool) fails any run that does not extend one of the listed templates.' },
  { id: 'q29', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/phases', domain: 'Pipelines', question: 'One job must build and test on Windows, Linux and macOS with the same steps. What is the simplest YAML approach?', options: ['Three copies of the job', 'A strategy matrix that sets the vmImage per entry', 'Three separate pipelines', 'A parallel strategy with maxParallel: 3'], answer: 1, explanation: 'A matrix strategy runs the job once per entry, and each entry can set variables such as imageName, used in pool.vmImage. A parallel strategy slices the same job across identical agents; it does not vary the OS.' },
  { id: 'q30', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/set-variables-scripts', domain: 'Pipelines', question: 'A step in job Build computes a version number that a later job must read. What must the step do?', code: 'echo "##vso[task.setvariable variable=ver;____]1.4.2"', options: ['isSecret=true', 'isOutput=true, with the step given a name', 'isReadOnly=true', 'Nothing: all variables flow between jobs'], answer: 1, explanation: 'Set isOutput=true and give the step a name. The later job declares dependsOn: Build and reads the value as dependencies.Build.outputs[\'stepName.ver\'].' },
  { id: 'q31', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/pipeline-triggers', domain: 'Pipelines', question: 'A release pipeline must start automatically whenever the CI pipeline finishes successfully on main. What do you add to the release pipeline\'s YAML?', options: ['A pipelines resource with a trigger on the CI pipeline', 'A schedules: block', 'A pr: trigger', 'A condition on the first stage'], answer: 0, explanation: 'resources.pipelines declares the upstream pipeline, and its trigger (with branch filters if you want them) queues this pipeline when that run completes. It also makes the CI artifacts available to download.' },
  { id: 'q32', learn: 'https://learn.microsoft.com/en-us/azure/app-service/deploy-staging-slots', domain: 'Pipelines', question: 'Your web app runs on Azure App Service. You want to warm up a new version and switch production traffic to it with almost no downtime, then switch back quickly if needed. What should you use?', options: ['Deployment slots with swap', 'A second App Service plan', 'Azure Front Door rules only', 'Redeploying the previous build'], answer: 0, explanation: 'Deploy to a staging slot, let it warm up, then swap it with production. If something goes wrong, swap back; the previous version is still in the other slot.' },
  { id: 'q33', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/targets/azure-sqldb', domain: 'Pipelines', question: 'A pipeline must deploy database schema changes, built as a DACPAC, to Azure SQL Database. Which task fits?', options: ['AzureWebApp@1', 'SqlAzureDacpacDeployment@1', 'AzureFileCopy@6', 'DotNetCoreCLI@2 with publish'], answer: 1, explanation: 'SqlAzureDacpacDeployment compares the DACPAC with the target database and applies the schema changes needed.' },
  { id: 'q34', learn: 'https://learn.microsoft.com/en-us/azure/developer/github/connect-from-azure-openid-connect', domain: 'Pipelines', question: 'A GitHub Actions workflow must deploy to Azure without storing a client secret in GitHub. What should you configure?', options: ['A personal access token stored as a secret', 'OpenID Connect with a federated credential on an Entra ID app or managed identity', 'The Azure publish profile stored as a secret', 'A self-hosted runner logged in with your account'], answer: 1, explanation: 'With OIDC, GitHub issues a short-lived token that Entra ID trusts through a federated credential, and azure/login exchanges it for an Azure token. No long-lived secret is stored.' },
  { id: 'q35', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/library/connect-to-azure', domain: 'Pipelines', question: 'An Azure DevOps service connection to Azure currently uses a service principal secret that expires every year. How do you remove the secret entirely?', options: ['Convert the connection to workload identity federation', 'Store the secret in Key Vault', 'Use a publish profile instead', 'Grant the pipeline Owner on the subscription'], answer: 0, explanation: 'Workload identity federation lets Azure Pipelines authenticate with a federated token, so there is no secret to rotate or leak. Key Vault only moves the secret somewhere else.' },
  { id: 'q36', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/agents/scale-set-agents', domain: 'Pipelines', question: 'Your self-hosted Azure Pipelines agents should scale out automatically when jobs queue up and scale in when idle, using Azure VMs. What should you use?', options: ['An Azure Virtual Machine Scale Set agent pool', 'More Microsoft-hosted parallel jobs', 'An availability set of agent VMs', 'Azure Container Instances with a fixed count'], answer: 0, explanation: 'A scale set agent pool lets Azure Pipelines grow and shrink the VM count to match demand, within the limits you set. Managed DevOps Pools is the newer fully managed alternative.' },
  { id: 'q37', learn: 'https://semver.org/', domain: 'Pipelines', question: 'Under Semantic Versioning, a library release removes a public method. The current version is 2.4.1. What should the new version be?', options: ['2.4.2', '2.5.0', '3.0.0', '2.4.1-breaking'], answer: 2, explanation: 'Breaking changes to the public API increase the MAJOR version and reset MINOR and PATCH to 0. New compatible features increase MINOR; compatible fixes increase PATCH.' },
  { id: 'q38', learn: 'https://learn.microsoft.com/en-us/azure/devops/artifacts/concepts/views', domain: 'Pipelines', question: 'Packages in an Azure Artifacts feed should be visible to consumers only after they pass testing. What feature supports this?', options: ['Feed views, with tested packages promoted to @Release', 'Upstream sources', 'Package retention policies', 'A separate organization'], answer: 0, explanation: 'Feed views such as @Prerelease and @Release show subsets of a feed. Promote a package to @Release once it passes, and point consumers at that view.' },
  { id: 'q39', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/approvals', domain: 'Pipelines', question: 'Before a deployment is promoted, the pipeline must confirm that no active Azure Monitor alerts are firing for the app. What should you add?', options: ['A Query Azure Monitor alerts check on the target environment', 'A post-job script that sends an email', 'A retention policy', 'A scheduled trigger'], answer: 0, explanation: 'Checks on an environment are evaluated before a stage deploys to it. The Query Azure Monitor alerts check passes only when no matching alerts are active, and can be re-evaluated over a set time window.' },
  { id: 'q40', learn: 'https://docs.github.com/en/actions/how-tos/reuse-automations/reuse-workflows', domain: 'Pipelines', question: 'Several GitHub repositories need the same deployment workflow. You want to maintain it once and call it from each repository. What should you create?', options: ['A reusable workflow triggered by workflow_call', 'A composite action in every repository', 'A workflow_dispatch trigger', 'A repository template'], answer: 0, explanation: 'A reusable workflow declares on: workflow_call and is called from other workflows with uses: owner/repo/.github/workflows/file.yml@ref. A repository template copies files once and does not stay in sync.' },
  { id: 'q41', learn: 'https://docs.github.com/en/actions/how-tos/deploy/configure-and-manage-deployments/manage-environments', domain: 'Pipelines', question: 'In GitHub Actions, a production secret must be usable only by jobs deploying to production, and only after a named reviewer approves. What should you configure?', options: ['An organization secret', 'An environment named production with required reviewers and an environment secret', 'A repository secret and a branch rule', 'An encrypted file in the repository'], answer: 1, explanation: 'Environment secrets are exposed only to jobs that reference that environment, and required reviewers pause those jobs until someone approves.' },
  { id: 'q42', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/test/flaky-test-management', domain: 'Pipelines', question: 'Some tests fail now and then without any code change, and they block unrelated pull requests. You want them identified and kept from failing builds while they are fixed. What should you use?', options: ['Flaky test management in Azure Pipelines test settings', 'Set continueOnError on the whole test job', 'Delete the failing tests', 'Increase the job timeout'], answer: 0, explanation: 'Flaky test detection marks tests that pass and fail on the same code, and can leave flaky failures out of the pass/fail result while still reporting them. continueOnError hides real failures too.' },

  { id: 'q43', learn: 'https://learn.microsoft.com/en-us/azure/devops/repos/security/configure-github-advanced-security-features', domain: 'Security', question: 'You need static analysis (SAST) of source code in Azure Repos, with results shown in Azure DevOps. What should you enable?', options: ['GitHub Advanced Security for Azure DevOps code scanning', 'Microsoft Defender for Cloud cost recommendations', 'A branch policy requiring two reviewers', 'Azure Policy on the subscription'], answer: 0, explanation: 'GitHub Advanced Security for Azure DevOps adds CodeQL code scanning, secret scanning and dependency scanning to Azure Repos and Azure Pipelines.' },
  { id: 'q44', learn: 'https://docs.github.com/en/code-security/concepts/secret-security/push-protection', domain: 'Security', question: 'You want to stop developers from pushing commits that contain credentials, rather than only being alerted afterwards. What should you turn on?', options: ['Secret scanning alerts only', 'Secret scanning push protection', 'Dependabot security updates', 'Required status checks'], answer: 1, explanation: 'Push protection scans pushes as they arrive and blocks those containing supported secret types. Alerts alone report secrets that have already reached the repository.' },
  { id: 'q45', learn: 'https://learn.microsoft.com/en-us/azure/role-based-access-control/best-practices', domain: 'Security', question: 'A pipeline deploys resources into one resource group. Following least privilege, how should its Azure identity be granted access?', options: ['Owner on the subscription', 'Contributor on that resource group only', 'Global Administrator in Entra ID', 'Reader on the subscription plus a shared admin key'], answer: 1, explanation: 'Scope the role to the smallest scope it needs, here the resource group, and choose the least powerful role that can do the job. Owner can also grant access to others, which a deployment rarely needs.' },
  { id: 'q46', learn: 'https://learn.microsoft.com/en-us/azure/defender-for-cloud/defender-for-containers-introduction', domain: 'Security', question: 'Container images in Azure Container Registry must be scanned for vulnerabilities, with findings shown alongside other security recommendations. What should you enable?', options: ['Microsoft Defender for Containers', 'Azure Monitor autoscale', 'ACR geo-replication', 'Azure Advisor cost alerts'], answer: 0, explanation: 'Defender for Containers assesses images in registries such as ACR for vulnerabilities and shows the results in Microsoft Defender for Cloud.' },
  { id: 'q47', learn: 'https://docs.github.com/en/code-security/concepts/supply-chain-security/dependency-review', domain: 'Security', question: 'A pull request should be blocked if it adds a dependency with a known vulnerability or a disallowed license. What can check this during pull request review on GitHub?', options: ['The dependency review action', 'CodeQL default setup', 'A CODEOWNERS entry', 'Dependabot version updates'], answer: 0, explanation: 'The dependency review action compares dependency changes in the pull request, and can fail the check for vulnerable versions or for licenses on an allow or deny list.' },

  { id: 'q48', learn: 'https://learn.microsoft.com/en-us/azure/azure-monitor/app/app-map', domain: 'Instrumentation', question: 'A request passes through five microservices, and you need to follow it end to end to find where time is spent. What should you implement?', options: ['Distributed tracing with Application Insights through OpenTelemetry', 'A separate Log Analytics workspace per service', 'Azure Advisor', 'Boot diagnostics on each VM'], answer: 0, explanation: 'Distributed tracing passes a shared trace context between services, so Application Insights can join the calls into one transaction view and application map.' },
  { id: 'q49', learn: 'https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-types', domain: 'Instrumentation', question: 'You need a notification when a VM\'s average CPU stays above 80% for 5 minutes. What should you create?', options: ['A metric alert rule with an action group', 'A diagnostic setting only', 'A workbook', 'An activity log alert'], answer: 0, explanation: 'Metric alert rules evaluate a platform metric over a time window and fire an action group (email, SMS, webhook and so on) when the condition is met. Activity log alerts react to control-plane events, not performance.' },
  { id: 'q50', learn: 'https://learn.microsoft.com/en-us/azure/azure-monitor/containers/kubernetes-monitoring-overview', domain: 'Instrumentation', question: 'You want node and pod performance, container logs and Kubernetes events from an AKS cluster in Azure Monitor. What should you enable?', options: ['Container insights', 'VM insights on each node', 'Application Insights availability tests', 'Network Watcher packet capture'], answer: 0, explanation: 'Container insights collects cluster, node and container metrics and logs from AKS into a Log Analytics workspace and adds ready-made views.' },
  { id: 'q51', learn: 'https://learn.microsoft.com/en-us/kusto/query/bin-function', domain: 'Instrumentation', question: 'Which KQL function groups timestamps into one-hour buckets in this query?', code: 'requests\n| where success == false\n| summarize failures = count() by ____(timestamp, 1h)', options: ['bin', 'group', 'round', 'bucket'], answer: 0, explanation: 'bin() rounds values down to a multiple of the given size, so summarize ... by bin(timestamp, 1h) gives one row per hour.' },

  // Pipelines, batch 2
  { id: 'q52', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/repos/azure-repos-git', domain: 'Pipelines', question: 'Your code is in Azure Repos. You added a pr: section to the YAML, but pull requests still do not start a build. What should you do?', options: ['Move the pr: section above trigger:', 'Add a build validation branch policy on the target branch', 'Set batch: true', 'Add pr: to every template'], answer: 1, explanation: 'YAML pr: triggers work for GitHub and Bitbucket Cloud repositories. For Azure Repos Git, pull request builds come from a build validation branch policy on the target branch.' },
  { id: 'q53', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/scheduled-triggers', domain: 'Pipelines', question: 'When does this schedule run, and what happens on a night with no new commits to main?', code: 'schedules:\n- cron: "0 2 * * 1-5"\n  displayName: Nightly\n  branches:\n    include:\n    - main', options: ['02:00 UTC Monday to Friday; skipped when nothing changed since the last successful scheduled run', '02:00 in the organization\'s time zone every day; always runs', '02:00 UTC Monday to Friday; always runs', 'Every 2 hours on weekdays'], answer: 0, explanation: 'Cron schedules are in UTC; 1-5 means Monday to Friday. always defaults to false, so a scheduled run is skipped if the branch has not changed since the last successful scheduled run. Set always: true to run anyway.' },
  { id: 'q54', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/conditions', domain: 'Pipelines', question: 'A stage must run only when earlier stages succeeded and the run is for the main branch. Which condition is correct?', options: ["condition: eq(variables['Build.SourceBranch'], 'main')", "condition: and(succeeded(), eq(variables['Build.SourceBranch'], 'refs/heads/main'))", 'condition: eq(Build.SourceBranchName, main)', "condition: succeeded('main')"], answer: 1, explanation: 'Build.SourceBranch holds the full ref, such as refs/heads/main. A custom condition replaces the default succeeded() check, so include succeeded() yourself or the stage can run after a failure.' },
  { id: 'q55', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/conditions', domain: 'Pipelines', question: 'A cleanup step must run even if earlier steps failed or the run was cancelled. Which condition should it use?', options: ['succeeded()', 'succeededOrFailed()', 'always()', 'failed()'], answer: 2, explanation: 'always() runs in every case, including cancellation. succeededOrFailed() runs after success or failure but not when the run is cancelled; failed() runs only after a failure.' },
  { id: 'q56', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/expressions', domain: 'Pipelines', question: 'Which expression syntax is evaluated when the YAML is compiled, before the run starts, and can add or remove whole steps?', options: ['$[ ]', '$( )', '${{ }}', '%{ }'], answer: 2, explanation: 'Template expressions ${{ }} are processed at compile time, so ${{ if }} can insert or skip steps. $[ ] runtime expressions are evaluated during the run, and $(var) macros are replaced just before each task runs.' },
  { id: 'q57', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/runtime-parameters', domain: 'Pipelines', question: 'When someone runs a pipeline manually, they must pick the target environment from a fixed list: dev, test or prod. What should you use?', options: ['A variable that is settable at queue time', 'A runtime parameter of type string with a values list', 'A variable group', 'A separate pipeline per environment'], answer: 1, explanation: 'Runtime parameters are typed and can restrict input to allowed values, shown as a drop-down when the run is queued. Queue-time variables accept any free text.' },
  { id: 'q58', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/deployment-jobs', domain: 'Pipelines', question: 'A deployment job targets an environment with ten virtual machines. You want to update two machines at a time. Which deployment strategy fits?', options: ['runOnce', 'rolling with maxParallel: 2', 'canary with increments: [2]', 'A matrix of ten jobs'], answer: 1, explanation: 'The rolling strategy replaces the application on a set number (or percentage) of VM targets per iteration, set with maxParallel. It is supported for virtual machine resources in an environment.' },
  { id: 'q59', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/deployment-jobs', domain: 'Pipelines', question: 'A deployment job runs a script from the repository and fails with "file not found". The same script works in a normal job. Why?', options: ['Deployment jobs cannot run scripts', 'Deployment jobs do not check out the source repository by default; add - checkout: self', 'The script needs a runtime parameter', 'Deployment jobs only run on Windows agents'], answer: 1, explanation: 'Deployment jobs download the pipeline artifacts but do not clone the repository automatically. Add a - checkout: self step if the job needs files from the repository.' },
  { id: 'q60', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/repos/multi-repo-checkout', domain: 'Pipelines', question: 'A pipeline needs helper scripts that live in a separate repository called tools in the same project. How do you get both repositories onto the agent?', options: ['Declare tools under resources.repositories and add - checkout: self and - checkout: tools', 'Use a Git submodule only', 'Copy the scripts into a variable group', 'Add tools to the trigger: branches list'], answer: 0, explanation: 'Declare the extra repository as a repository resource and check it out with its own checkout step. With more than one checkout, each repository lands in its own folder under the sources directory.' },
  { id: 'q61', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/container-phases', domain: 'Pipelines', question: 'Every build must run with exactly the same toolchain, which is published as a container image. How can all steps of a job run inside that image?', options: ['A container job: set container: on the job', 'A service container', 'A Docker@2 build task', 'An Azure Container Instances deployment'], answer: 0, explanation: 'In a container job, the agent starts the image and runs every step inside it, so the toolchain is identical on every run. Service containers run alongside the job, for example a test database.' },
  { id: 'q62', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/tasks/reference/docker-v2', domain: 'Pipelines', question: 'In one step, a pipeline must build an image from a Dockerfile and push it to Azure Container Registry. What should you use?', options: ['Docker@2 with command buildAndPush and a Docker registry service connection', 'AzureWebAppContainer@1', 'PublishPipelineArtifact@1', 'KubernetesManifest@1 with action bake'], answer: 0, explanation: 'Docker@2 with buildAndPush builds the image and pushes it, with tags, to the registry named in its Docker registry service connection.' },
  { id: 'q63', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/tasks/reference/kubernetes-manifest-v1', domain: 'Pipelines', question: 'A pipeline must apply Kubernetes manifest files to AKS and substitute the image tag that was just built. Which task is designed for this?', options: ['AzureFunctionApp@2', 'KubernetesManifest@1 with action deploy', 'AzureResourceManagerTemplateDeployment@3', 'AzureWebApp@1'], answer: 1, explanation: 'KubernetesManifest with action deploy applies manifests through a Kubernetes service connection and can replace image references with the tags from the containers input. It also supports canary deployments.' },
  { id: 'q64', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/tasks/reference/manual-validation-v0', domain: 'Pipelines', question: 'You add ManualValidation@0 so that a person must confirm before a pipeline continues. Where must this task run?', options: ['In a job on a Microsoft-hosted agent', 'In an agentless job (pool: server)', 'In a container job', 'In any job, as the first step'], answer: 1, explanation: 'ManualValidation pauses the run until someone resumes or rejects it. It only works in an agentless (server) job, so no agent is held while it waits.' },
  { id: 'q65', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/licensing/concurrent-jobs', domain: 'Pipelines', question: 'In a private project, pipeline runs queue up and run one at a time on Microsoft-hosted agents, and teams wait for each other. What removes the wait?', options: ['Increase the job timeout', 'Buy more Microsoft-hosted parallel jobs', 'Set batch: true', 'Split the pipeline into more stages'], answer: 1, explanation: 'Parallel jobs set how many jobs can run at the same time in the organization. Each extra Microsoft-hosted (or self-hosted) parallel job lets one more job run at once.' },
  { id: 'q66', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/policies/retention', domain: 'Pipelines', question: 'Runs are deleted after 30 days, but the run that produced this quarter\'s production release must be kept. What should you do?', options: ['Change the project retention to never delete anything', 'Retain that run with a retention lease', 'Download the logs to a laptop', 'Re-run the pipeline every month'], answer: 1, explanation: 'Retaining a run, from the run menu or through a retention lease in the pipeline or API, keeps that run and its artifacts while normal retention keeps cleaning up the rest.' },
  { id: 'q67', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/resources', domain: 'Pipelines', question: 'A new pipeline\'s first run stops with "This pipeline needs permission to access a resource". What resolves it?', options: ['Delete and recreate the service connection', 'A user with permission on that resource permits the pipeline, or adds it to the resource\'s pipeline permissions', 'Make the project public', 'Change the agent pool to Microsoft-hosted'], answer: 1, explanation: 'Protected resources such as service connections, environments and agent pools must authorize each pipeline that uses them. Someone allowed to manage the resource can choose Permit on the run, or grant the pipeline access in the resource settings.' },
  { id: 'q68', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/tasks/reference/publish-test-results-v2', domain: 'Pipelines', question: 'Your test runner writes JUnit XML files. You want the results in the run\'s Tests tab with pass and fail trends. What should you add?', options: ['PublishTestResults@2 with testResultsFormat: JUnit', 'PublishPipelineArtifact@1 for the XML files', 'A script that prints the XML to the log', 'A dashboard Markdown widget'], answer: 0, explanation: 'PublishTestResults reads JUnit, NUnit, VSTest, xUnit or CTest result files and publishes them to the run, which fills the Tests tab and analytics. Publishing them as an artifact only stores the files.' },
  { id: 'q69', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/run-number', domain: 'Pipelines', question: 'Which name: value gives run numbers like 20260929.3, restarting the counter every day?', options: ['name: $(Build.BuildId)', 'name: $(Date:yyyyMMdd)$(Rev:.r)', 'name: $(Rev:r)$(Date:yyyyMMdd)', 'name: $(Build.SourceVersion)'], answer: 1, explanation: '$(Rev:r) counts up while the rest of the run number stays the same, and starts at 1 again when it changes, which here is each new date. BuildId never resets, and SourceVersion is the commit ID.' },
  { id: 'q70', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/stages', domain: 'Pipelines', question: 'Stages Build, Test_EU and Test_US are listed in that order. Test_US waits for Test_EU, but both test stages should start together once Build finishes. What should you set?', options: ['dependsOn: Build on both test stages', 'dependsOn: [] on both test stages', 'condition: always() on Test_US', 'A matrix on the Build stage'], answer: 0, explanation: 'By default each stage depends on the stage before it. Pointing both test stages at Build lets them run in parallel after it. dependsOn: [] would remove every dependency, so they would not wait for Build at all.' },
  { id: 'q71', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/environments-virtual-machines', domain: 'Pipelines', question: 'A YAML pipeline must deploy to on-premises virtual machines with a deployment job, and keep deployment history per machine. What should you set up?', options: ['Add the VMs as virtual machine resources in an environment by running its registration script on each VM', 'Create a service connection per VM with a password', 'Install Microsoft-hosted agents on the VMs', 'Use a variable group listing the VM names'], answer: 0, explanation: 'Virtual machine resources in an environment run an agent registered to that environment. Deployment jobs can then target them, including with a rolling strategy and tags, and the environment shows each machine\'s deployments.' },
  { id: 'q72', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/approvals', domain: 'Pipelines', question: 'Two runs must never deploy to Production at the same time; a later run should wait until the current one finishes. Which check should you add to the environment?', options: ['Business hours', 'Exclusive lock', 'Invoke REST API', 'Required template'], answer: 1, explanation: 'The exclusive lock check lets only one run use the environment at a time. With lockBehavior you choose whether queued runs go in order (sequential) or only the newest one proceeds (runLatest).' },
  { id: 'q73', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/deployment-jobs', domain: 'Pipelines', question: 'In a runOnce deployment job, rollback steps must run automatically if the deployment fails. Where do they go?', options: ['In the on: failure lifecycle hook', 'In the preDeploy hook', 'In a separate pipeline triggered manually', 'In the routeTraffic hook'], answer: 0, explanation: 'Deployment strategies provide lifecycle hooks: preDeploy, deploy, routeTraffic, postRouteTraffic, and on: failure / on: success. Steps under on: failure run only when the deployment fails, which makes them the natural place for rollback.' },
  { id: 'q74', learn: 'https://docs.github.com/en/actions/how-tos/write-workflows/choose-when-workflows-run/control-workflow-concurrency', domain: 'Pipelines', question: 'In GitHub Actions, only one production deployment may run at a time; a new one should wait for the current one. What should you add to the deploy job?', options: ['concurrency: production', 'timeout-minutes: 60', 'continue-on-error: true', 'permissions: write-all'], answer: 0, explanation: 'Jobs or workflows in the same concurrency group run one at a time; a new run waits as pending. Add cancel-in-progress: true only if the newer run should cancel the running one instead.' },
  { id: 'q75', learn: 'https://docs.github.com/en/actions/reference/workflows-and-actions/dependency-caching', domain: 'Pipelines', question: 'A GitHub Actions workflow reinstalls npm packages on every run. How do you reuse them when package-lock.json has not changed?', options: ["actions/cache with a key built from hashFiles('**/package-lock.json')", 'Upload the node_modules folder as a release asset', 'Commit node_modules to the repository', 'Use a larger runner'], answer: 0, explanation: 'actions/cache restores a saved folder when the key matches, and a key built from the lock file hash changes only when dependencies change. Setup actions such as actions/setup-node also offer a built-in cache option.' },
  { id: 'q76', learn: 'https://docs.github.com/en/actions/how-tos/write-workflows/choose-what-workflows-do/run-job-variations', domain: 'Pipelines', question: 'A GitHub Actions test job must run on Node.js 20, 22 and 24 without copying the job three times. What should you use?', options: ['strategy.matrix with a list of node versions', 'Three workflow files', 'needs: with three jobs', 'A reusable workflow called three times'], answer: 0, explanation: 'A matrix creates one job per combination of values, for example node: [20, 22, 24], and each job reads its value through the matrix context, such as in actions/setup-node.' },
  { id: 'q77', learn: 'https://learn.microsoft.com/en-us/azure/devops/artifacts/quickstarts/universal-packages', domain: 'Pipelines', question: 'You need to version and share a set of large tool binaries that are not NuGet, npm, Maven or Python packages. Which Azure Artifacts package type fits?', options: ['Universal Packages', 'A NuGet package with the binaries inside', 'A Git LFS repository in Azure Artifacts', 'Pipeline artifacts kept forever'], answer: 0, explanation: 'Universal Packages store any set of files, with a name and version, in an Azure Artifacts feed, and are published and downloaded with the Azure CLI or the UniversalPackages task.' },
  { id: 'q78', learn: 'https://learn.microsoft.com/en-us/azure/developer/terraform/store-state-in-azure-storage', domain: 'Pipelines', question: 'Several pipelines run Terraform against the same environment. State must be shared and protected from two runs writing at once. What should you configure?', options: ['The azurerm backend with state in an Azure Storage blob container', 'A local terraform.tfstate committed to the repository', 'A pipeline artifact holding the state file', 'A variable group containing the state'], answer: 0, explanation: 'The azurerm backend keeps state in a blob, and Terraform takes a blob lease while it works, so concurrent runs cannot both write. State in the repository or in artifacts is not locked and can leak secrets.' },
  { id: 'q79', learn: 'https://learn.microsoft.com/en-us/azure/azure-resource-manager/bicep/deploy-what-if', domain: 'Pipelines', question: 'Before a pipeline deploys a Bicep file to a resource group, reviewers want to see which resources would be created, changed or deleted. What should the pipeline run first?', options: ['az deployment group what-if', 'az bicep build only', 'az group delete --dry-run', 'az deployment group validate only'], answer: 0, explanation: 'what-if compares the template with the current state of the resource group and lists the create, modify and delete changes without applying them. validate only checks the template is valid.' },
  { id: 'q80', learn: 'https://learn.microsoft.com/en-us/azure/devops/pipelines/process/templates', domain: 'Pipelines', question: 'Complete the YAML so the value Release is passed into the steps template.', code: 'steps:\n- template: build-steps.yml\n  ______:\n    configuration: Release', options: ['variables', 'parameters', 'inputs', 'env'], answer: 1, explanation: 'Templates receive values through parameters, which the template declares and reads as ${{ parameters.configuration }}. inputs belongs to tasks, and env sets environment variables for a script step.' }
];
